import java.util.ArrayList;
import java.util.List;

class Solution {
    public List<String> findWords(char[][] board, String[] words) {
        List<String> found = new ArrayList<>();
        for (String word : words) {
            boolean matched = false;
            for (int row = 0; row < board.length && !matched; row++) {
                for (int col = 0; col < board[0].length && !matched; col++) {
                    if (board[row][col] == word.charAt(0) && search(board, word, row, col, 0)) matched = true;
                }
            }
            if (matched) found.add(word);
        }
        return found;
    }
    private boolean search(char[][] board, String word, int row, int col, int index) {
        if (row < 0 || row >= board.length || col < 0 || col >= board[0].length || board[row][col] != word.charAt(index)) return false;
        if (index == word.length() - 1) return true;
        char saved = board[row][col];
        board[row][col] = '#';
        boolean found = search(board, word, row - 1, col, index + 1)
                || search(board, word, row + 1, col, index + 1)
                || search(board, word, row, col - 1, index + 1)
                || search(board, word, row, col + 1, index + 1);
        board[row][col] = saved;
        return found;
    }
}

