import java.util.ArrayList;
import java.util.List;

class Solution {
    private static class TrieNode {
        TrieNode[] children = new TrieNode[26];
        String word;
    }
    private TrieNode root = new TrieNode();
    private List<String> found = new ArrayList<>();
    public List<String> findWords(char[][] board, String[] words) {
        root = new TrieNode();
        found = new ArrayList<>();
        for (String word : words) {
            TrieNode node = root;
            for (int index = 0; index < word.length(); index++) {
                int letter = word.charAt(index) - 'a';
                if (node.children[letter] == null) node.children[letter] = new TrieNode();
                node = node.children[letter];
            }
            node.word = word;
        }
        for (int row = 0; row < board.length; row++) for (int col = 0; col < board[0].length; col++) search(board, row, col, root);
        return found;
    }
    private void search(char[][] board, int row, int col, TrieNode parent) {
        if (row < 0 || row >= board.length || col < 0 || col >= board[0].length || board[row][col] == '#') return;
        int letter = board[row][col] - 'a';
        TrieNode node = parent.children[letter];
        if (node == null) return;
        if (node.word != null) { found.add(node.word); node.word = null; }
        char saved = board[row][col];
        board[row][col] = '#';
        search(board, row - 1, col, node);
        search(board, row + 1, col, node);
        search(board, row, col - 1, node);
        search(board, row, col + 1, node);
        board[row][col] = saved;
        if (node.word == null && hasNoChildren(node)) parent.children[letter] = null;
    }
    private boolean hasNoChildren(TrieNode node) {
        for (TrieNode child : node.children) if (child != null) return false;
        return true;
    }
}
